#!/usr/bin/env python3
"""Generate src/gen/prefectures.circom: UTF-8 bytes of the 47 prefecture names (JIS X 0401 order)."""
import os

P = ("北海道 青森県 岩手県 宮城県 秋田県 山形県 福島県 茨城県 栃木県 群馬県 埼玉県 千葉県 東京都 神奈川県 "
     "新潟県 富山県 石川県 福井県 山梨県 長野県 岐阜県 静岡県 愛知県 三重県 滋賀県 京都府 大阪府 兵庫県 "
     "奈良県 和歌山県 鳥取県 島根県 岡山県 広島県 山口県 徳島県 香川県 愛媛県 高知県 福岡県 佐賀県 長崎県 "
     "熊本県 大分県 宮崎県 鹿児島県 沖縄県").split()
assert len(P) == 47

rows = [list(p.encode()) for p in P]
out = [
    "pragma circom 2.1.6;",
    "",
    "// Generated by scripts/gen_prefectures.py (JIS X 0401 order, index 0 = code 1). UTF-8 bytes, zero padded to 12.",
    "function PREF_LEN() {",
    "    return [" + ", ".join(str(len(r)) for r in rows) + "];",
    "}",
    "",
    "function PREF_BYTES() {",
    "    return [",
]
out += [
    "        [" + ", ".join(map(str, r + [0] * (12 - len(r)))) + "]" + ("," if i < 46 else "") + f" // {i + 1} {P[i]}"
    for i, r in enumerate(rows)
]
out += ["    ];", "}", ""]

dst = os.path.join(os.path.dirname(__file__), "..", "src", "gen", "prefectures.circom")
os.makedirs(os.path.dirname(dst), exist_ok=True)
with open(dst, "w") as f:
    f.write("\n".join(out))
